#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) { ilen = fread(ibuf, 1, sizeof ibuf, stdin); ipos = 0; if (!ilen) return -1; }
    return ibuf[ipos++];
}
static inline long long readInt() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

int main() {
    int n = readInt();
    readInt();  // M equals N
    vector<int> a((size_t)n * n);
    for (auto& x : a) x = readInt();
    string out;
    out.reserve((size_t)n * n * 12);
    char tmp[16];
    // New row c is original column c read from bottom to top.
    for (int c = 0; c < n; c++) {
        for (int r = n - 1; r >= 0; r--) {
            int len = snprintf(tmp, sizeof tmp, "%d", a[(size_t)r * n + c]);
            out.append(tmp, len);
            out += r ? ' ' : '\n';
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static int readInt() throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        int x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        readInt(); // M equals N
        int[] a = new int[n * n];
        for (int i = 0; i < a.length; i++) a[i] = readInt();
        StringBuilder out = new StringBuilder(n * n * 12);
        // New row c is original column c read from bottom to top.
        for (int c = 0; c < n; c++) {
            for (int r = n - 1; r >= 0; r--) out.append(a[r * n + c]).append(r > 0 ? ' ' : '\n');
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int {
	c, _ := reader.ReadByte()
	for c != '-' && (c < '0' || c > '9') {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	x := 0
	for c >= '0' && c <= '9' {
		x = x*10 + int(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	n := readInt()
	readInt() // M equals N
	a := make([]int32, n*n)
	for i := range a {
		a[i] = int32(readInt())
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	buf := []byte{}
	// New row c is original column c read from bottom to top.
	for c := 0; c < n; c++ {
		buf = buf[:0]
		for r := n - 1; r >= 0; r-- {
			buf = strconv.AppendInt(buf, int64(a[r*n+c]), 10)
			if r > 0 {
				buf = append(buf, ' ')
			} else {
				buf = append(buf, '\n')
			}
		}
		w.Write(buf)
	}
}
